func pricingTypeAr(p string) string {
	switch p {
	case "free":
		return "مجاني"
	case "subscription":
		return "اشتراك دوري"
	case "paid":
		return "مدفوع"
	case "monthly":
		return "شهري"
	case "per_project":
		return "لكل مشروع"
	case "hourly":
		return "بالساعة"
	default:
		return p
	}
}

func pricingBadgeClass(p string) string {
	switch p {
	case "free":
		return "badge-emerald"
	case "subscription":
		return "badge-purple"
	case "paid":
		return "badge-sky"
	case "monthly":
		return "badge-amber"
	default:
		return "badge-slate"
	}
}

